def __init__(self, tokens):
	Converter.__init__(self, tokens)
	tokenDictionary = {
		"Blink": ("blink", True),
		"Invert": ("invert", True)
	}
	self.blink = False
	self.invert = False
	self.blinkTime = 500
	parse = ","
	tokens = tokens.replace(";", parse)  # Some builds use ";" as a separator, most use ",".
	tokens = [x.strip() for x in tokens.split(parse)]
	for token in tokens:
		if token.isdigit():
			self.blinkTime = int(token)
			continue
		variable, value = tokenDictionary.get(token, (None, None))
		if variable:
			setattr(self, variable, value)
		elif token:
			print(f"[ConditionalShowHide] Error: Converter argument '{token}' is invalid!")
	if self.blink:
		self.timer = eTimer()
		self.timer.callback.append(self.blinker)
	else:
		self.timer = None

