				backgroundColor = value
			elif attrib == "foregroundColor":
				foregroundColor = value
			else:
				attribs.append((attrib, value))
		if foregroundColor:
			attribs.append(("foregroundColor", foregroundColor))
		if backgroundColor:
			attribs.append(("backgroundColor", backgroundColor))
